CREATE OR REPLACE FUNCTION public.guard_review_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.owner_id<>OLD.owner_id OR NEW.legacy_post_id IS DISTINCT FROM OLD.legacy_post_id THEN RAISE EXCEPTION 'Review ownership and original post links cannot change'; END IF; IF NEW.status<>'published' AND (NEW.legacy_post_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.beauty_posts p WHERE p.review_id=NEW.id)) THEN RAISE EXCEPTION 'Remove the public Feed post before making this review private'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_review_privacy BEFORE UPDATE ON public.beauty_reviews FOR EACH ROW EXECUTE FUNCTION public.guard_review_privacy();